# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA TEMİZLİK (TAHÂRET) KAVRAMI VE AYET-HADİSLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tahâret Kavramı ve Kapsamı</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Tahâret: Maddi ve manevi kirden arınmak</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Hadesten Tahâret (Hükmi Temizlik):</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#334155">Abdest, gusül (boy abdesti) ve teyemmüm ile</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#334155">gözle görülmeyen manevi kirlilikten arınmak.</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Necâsetten Tahâret (Maddi Temizlik):</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">Beden, elbise ve ibadet edilecek yeri gözle</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">görülen maddi kirlerden (necasetten) temizlemek.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kur\'an ve Sünnette Temizlik Vurgusu</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Müddessir Suresi 4-5. Ayetler (İlk Emirler):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">"Elbiseni tertemiz tut ve kötü şeyleri terk et!"</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Bakara Suresi 222. Ayet:</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">"Şüphesiz Allah çok tövbe edenleri (manevi arınanları)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">ve çok temizlenenleri sever."</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">• Hadis-i Şerif: «Temizlik imanın yarısıdır.»</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#334155">(Müslim, Tahâret, 1)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MADDİ TEMİZLİK: BEDEN, ELBİSE VE ÇEVRE TEMİZLİĞİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Beden Temizliği</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#334155">• Yemekten önce ve sonra</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#334155">elleri yıkamak (bereket vesilesi)</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#334155">• Ağız ve diş sağlığını korumak</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#334155">(Misvak / diş fırçası sünneti)</text>\n  <text x="125" y="180" text-anchor="middle" font-size="11" fill="#334155">• Tırnak kesmek, saç-sakal bakımı</text>\n  <text x="125" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Cuma ve bayram günleri</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">yıkanıp güzel koku sürünmek</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">2. Elbise ve Mekan Temizliği</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#334155">• Kıyafetlerin temiz, düzenli</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" fill="#334155">ve sade olmasına özen göstermek</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11" fill="#334155">• Namaz kılınacak elbise ve</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#334155">seccadenin necasetten arınması</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#334155">• Evin, okulun ve mescitlerin</text>\n  <text x="350" y="198" text-anchor="middle" font-size="11" fill="#334155">havalandırılıp temiz tutulması</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">(A\'râf Suresi, 31. Ayet)</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">3. Çevre Temizliği</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#334155">• "Yeryüzü bana mescit ve</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#334155">temiz kılındı." (Hadis-i Şerif)</text>\n  <text x="575" y="138" text-anchor="middle" font-size="11" fill="#334155">• Suları, sokakları ve ağaç</text>\n  <text x="575" y="156" text-anchor="middle" font-size="11" fill="#334155">gölgelerini kirletmemek</text>\n  <text x="575" y="180" text-anchor="middle" font-size="11" fill="#334155">• Yoldaki rahatsız edici taş ve</text>\n  <text x="575" y="198" text-anchor="middle" font-size="11" fill="#334155">engelleri kaldırmak (Sadaka)</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">• Su kaynaklarını israf etmemek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MANEVİ TEMİZLİK (KALP VE AHLAK ARINMASI)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Kalbi Kirleten Manevi Hastalıklar</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Şirk ve İnkâr (Tevhid inancından uzaklaşmak)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Kibir (Büyüklenmek) ve Riya (Gösteriş)</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Haset (Kıskançlık), Kin ve Nefret</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Yalan, Gıybet (Dedikodu) ve İftira</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Hile, Haram Kazanç ve Kul Hakkı Yemek</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#881337">Manevi kirler insanın ruhunu ve toplum huzurunu bozar.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Manevi Temizlik ve Arınma Yolları</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">1. Tövbe ve İstiğfar:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Günahlardan pişman olup Allah\'tan bağışlanma dilemek.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">2. İhlas, Doğruluk (Sıdk) ve Güzel Ahlak:</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">Niyeti gösterişten arındırıp dürüst ve merhametli olmak.</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">3. İbadetler ve Zekât/Sadaka:</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">Namaz insanı kötülükten alıkoyar; zekât ise malı ve</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#334155">nefsi cimrilik kirinden temizler (Tevbe, 103).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
